DROP TABLE IF EXISTS `sys_dept`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `sys_dept` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `tenant_id` bigint NOT NULL COMMENT '租户ID【多租户隔离字段】',
  `company_id` bigint NOT NULL COMMENT '所属公司ID',
  `dept_code` varchar(64) NOT NULL COMMENT '部门编码',
  `dept_name` varchar(100) NOT NULL COMMENT '部门名称',
  `parent_id` bigint NOT NULL DEFAULT '0' COMMENT '上级部门ID,0为顶级',
  `ancestors` varchar(500) DEFAULT '' COMMENT '祖级路径,逗号分隔',
  `dept_level` int NOT NULL DEFAULT '1' COMMENT '层级,从1开始',
  `leader_id` bigint DEFAULT NULL COMMENT '部门负责人用户ID(审批默认取此人)',
  `cost_center` varchar(64) DEFAULT NULL COMMENT '成本中心编码',
  `sort` int NOT NULL DEFAULT '0' COMMENT '排序',
  `status` varchar(20) NOT NULL DEFAULT 'NORMAL' COMMENT '状态:NORMAL正常/DISABLED停用',
  `remark` varchar(500) DEFAULT NULL,
  `create_by` bigint DEFAULT NULL,
  `create_time` datetime DEFAULT CURRENT_TIMESTAMP,
  `update_by` bigint DEFAULT NULL,
  `update_time` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `del_flag` tinyint NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_tenant_dept_code` (`tenant_id`,`dept_code`),
  KEY `idx_tenant` (`tenant_id`),
  KEY `idx_tenant_parent` (`tenant_id`,`parent_id`),
  KEY `idx_tenant_company` (`tenant_id`,`company_id`)
) ENGINE=InnoDB AUTO_INCREMENT=10295 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='部门';
